function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is an integer from -10^9 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k must be between 1 and the length of nums.';
  if (k % 2 === 0) return 'k must be odd.';
  if (nums.length * k > 1000000) return 'n * k must be at most 10^6.';
  return null;
}

