function maximumStrength(nums, k) {
  const open = new Array(k + 1).fill(-Infinity);
  const best = new Array(k + 1).fill(-Infinity);
  best[0] = 0;
  for (const value of nums) {
    for (let j = k; j >= 1; j--) {
      const sign = j % 2 === 1 ? 1 : -1;
      const weight = sign * (k - j + 1);
      open[j] = Math.max(open[j], best[j - 1]) + weight * value;
      best[j] = Math.max(best[j], open[j]);
    }
  }
  return best[k];
}

