function maximumStrength(nums, k) {
  let answer = -Infinity;
  const pick = (start, index, total) => {
    if (index === k) {
      answer = Math.max(answer, total);
      return;
    }
    const factor = (index % 2 === 0 ? 1 : -1) * (k - index);
    for (let from = start; from < nums.length; from++) {
      let sum = 0;
      for (let to = from; to < nums.length; to++) {
        sum += nums[to];
        pick(to + 1, index + 1, total + factor * sum);
      }
    }
  };
  pick(0, 0, 0);
  return answer;
}

