function generate(rand, size) {
  const randInt = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = randInt(1, 8);
    const k = 2 * randInt(0, Math.floor((n - 1) / 2)) + 1;
    const span = rand() < 0.2 ? 1000000000 : 10;
    const bias = rand() < 0.3 ? -Math.floor(span / 2) : 0;
    const nums = Array.from({ length: n }, () => Math.max(-span, Math.min(span, randInt(-span, span) + bias)));
    return [nums, k];
  }
  const n = randInt(1000, 2000);
  const maxK = Math.min(n, Math.floor(1000000 / n));
  const k = 2 * randInt(0, Math.floor((maxK - 1) / 2)) + 1;
  const span = rand() < 0.5 ? 1000000000 : 1000;
  const nums = Array.from({ length: n }, () => randInt(-span, span));
  return [nums, k];
}
